struct Point:
    var x: Float64
    var y: Float64

    fn __init__(inout self, x: Float64, y: Float64):
        self.x = x
        self.y = y

    fn distance(self, other: Point) -> Float64:
        let dx = self.x - other.x
        let dy = self.y - other.y
        return (dx * dx + dy * dy) ** 0.5

    fn __str__(self) -> String:
        return "Point(" + String(self.x) + ", " + String(self.y) + ")"

    fn __add__(self, other: Point) -> Point:
        return Point(self.x + other.x, self.y + other.y)

fn use_point():
    let p1 = Point(0.0, 0.0)
    let p2 = Point(3.0, 4.0)
    print(p1.distance(p2))   # 5.0
    let p3 = p1 + p2
    print(p3)
```

Mojo structs are **value types** (stack-allocated), unlike Python classes (heap-allocated). Structs can define operators (`__add__`, `__str__`, etc.) and are the primary way to write high-performance code.

