# Trait — interface/protocol
trait Animal:
    fn speak(self) -> String: ...
    fn name(self) -> String: ...

struct Dog(Animal):
    var dog_name: String

    fn __init__(inout self, name: String):
        self.dog_name = name

    fn speak(self) -> String:
        return "Woof!"

    fn name(self) -> String:
        return self.dog_name

struct Cat(Animal):
    var cat_name: String

    fn __init__(inout self, name: String):
        self.cat_name = name

    fn speak(self) -> String:
        return "Meow!"

    fn name(self) -> String:
        return self.cat_name

# Generic function constrained to Animal trait
fn make_noise[T: Animal](animal: T):
    print(animal.name(), "says:", animal.speak())

fn test_traits():
    let dog = Dog("Rex")
    let cat = Cat("Whiskers")
    make_noise(dog)
    make_noise(cat)
