from sys.info import simdwidthof

fn simd_add():
    # SIMD = process multiple values simultaneously
    var a = SIMD[DType.float32, 4](1.0, 2.0, 3.0, 4.0)
    var b = SIMD[DType.float32, 4](5.0, 6.0, 7.0, 8.0)
    var c = a + b          # [6.0, 8.0, 10.0, 12.0]
    print(c)

    var sum = c.reduce_add()   # 34.0
    var result = a.fma(b, c)   # fused multiply-add: a*b + c

from algorithm import vectorize

fn vectorized_add(a: DTypePointer[DType.float32],
                  b: DTypePointer[DType.float32],
                  c: DTypePointer[DType.float32],
                  n: Int):
    alias width = simdwidthof[DType.float32]()

    @parameter
    fn add_chunk[w: Int](idx: Int):
        let va = a.load[width=w](idx)
        let vb = b.load[width=w](idx)
        c.store[width=w](idx, va + vb)

    vectorize[add_chunk, width](n)
```

SIMD is the key to Mojo's ML performance — process 4, 8, or 16 values with a single CPU instruction.

