from python import Python

def use_numpy():
    let np = Python.import_module("numpy")
    let arr = np.array([1, 2, 3, 4, 5])
    print(arr.mean())    # 3.0
    print(arr.std())

    let zeros = np.zeros((3, 3))
    print(zeros)

def use_torch():
    let torch = Python.import_module("torch")
    let tensor = torch.randn(3, 4)
    print(tensor)
    print(tensor.shape)

def use_matplotlib():
    let plt = Python.import_module("matplotlib.pyplot")
    let np = Python.import_module("numpy")
    let x = np.linspace(0, 2 * np.pi, 100)
    let y = np.sin(x)
    plt.plot(x, y)
    plt.savefig("sine.png")

def main():
    use_numpy()
    use_torch()
```

Mojo can call any Python package via `Python.import_module`. This gives access to the entire Python ecosystem (NumPy, PyTorch, etc.) while writing performance-critical code in Mojo.
